-- ai-career-essentials
insert into public.modules(course_id,title,description,sort_order,published)
select c.id,'AI Literacy','Understand what modern AI systems can and cannot reliably do.',1,true
from public.courses c join public.programmes p on p.id=c.programme_id
where p.slug='ai-career-essentials' and c.slug='core-pathway'
  and not exists (select 1 from public.modules mx where mx.course_id=c.id and mx.title='AI Literacy')
;
insert into public.lessons(module_id,title,slug,content,estimated_minutes,sort_order,published)
select m.id,'AI systems','ai-systems','{"type": "course_note", "summary": "Generative AI predicts and produces patterns from learned representations. Distinguish models from applications, data, interfaces and the workflows built around them.", "sections": [{"heading": "Core note", "body": "Generative AI predicts and produces patterns from learned representations. Distinguish models from applications, data, interfaces and the workflows built around them."}, {"heading": "Practice", "body": "Apply this idea to a realistic AI & Career Essentials Core Pathway scenario. Write down your assumptions, the action you would take, and the evidence you would use to evaluate the result."}, {"heading": "Reflection", "body": "What changed in your understanding after completing this lesson? Record one practical action you can demonstrate in your portfolio or next learning activity."}], "key_takeaways": ["Generative AI predicts and produces patterns from learned representations.", "Use the concept in a practical scenario rather than memorising the definition.", "Record evidence of application and review what you would improve next time."]}'::jsonb,15,1,true
