where p.slug='ai-career-essentials' and c.slug='core-pathway' and m.title='AI Literacy'
on conflict(module_id,slug) do update set title=excluded.title,content=excluded.content,estimated_minutes=excluded.estimated_minutes,sort_order=excluded.sort_order,published=excluded.published;
